#pragma warning disable CS8601 // Possible null reference assignment.#pragma warning disable CS8604 // Possible null reference argument.using FirstGearGames.FishNet.CodeAnalysis.Constants;using System.Collections.Generic;using Microsoft.CodeAnalysis;using System.Linq;using FirstGearGames.CodeAnalysis.Extensions;using FirstGearGames.CodeAnalysis.Helpers;namespace FirstGearGames.FishNet.CodeAnalysis.CodeBuilding.Serializers{    public enum AddSerializerType    {        Unset,        Full,        Delta,    }    public enum GetSerializerType    {        Full,        Delta,        FavorFull,        FavorDelta,    }    public class SerializerMethods    {        //Writers.        private readonly Dictionary<string, SerializerMethodData> _writeMethods = new();        private readonly Dictionary<string, SerializerMethodData> _writeDeltaMethods = new();        //Readers        private readonly Dictionary<string, SerializerMethodData> _readMethods = new();        private readonly Dictionary<string, SerializerMethodData> _readDeltaMethods = new();        //Consts.        public const string Generated_ValueParameter_Prefix = "value";        public void Initialize(IAssemblySymbol runtimeAssemblySymbol)        {            Log("");            Log($"Initialize.");            AddDefaultWriteMethods(runtimeAssemblySymbol);            AddDefaultReadMethods(runtimeAssemblySymbol);        }        #region Add/get serializers        /// <summary>        /// Adds to writers.        /// </summary>        public void AddWriteMethod(SerializerMethodData sm, AddSerializerType addType)        {            Dictionary<string, SerializerMethodData> dict = (addType == AddSerializerType.Full) ? _writeMethods : _writeDeltaMethods;            if (dict.ContainsKey(sm.TypeFullName))            {                Log($"{addType} writer already exists for {sm.TypeFullName}.");            }            else            {                dict[sm.TypeFullName] = sm;                Log($"Added {addType} writer method {sm.MethodName} for {sm.TypeFullName}. SmType {sm.GetType().Name}");            }        }        /// <summary>        /// Adds to readers.        /// </summary>        public void AddReadMethod(SerializerMethodData sm, AddSerializerType addType)        {            Dictionary<string, SerializerMethodData> dict = (addType == AddSerializerType.Full) ? _readMethods : _readDeltaMethods;            if (dict.ContainsKey(sm.TypeFullName))            {                Log($"{addType} reader method already exists for {sm.TypeFullName}.");            }            else            {                dict[sm.TypeFullName] = sm;                Log($"Added {addType} reader method {sm.MethodName} for {sm.TypeFullName}.");            }        }        /// <summary>        /// Returns a writer.        /// </summary>        public SerializerMethodData GetWriteMethod(string typeFullName, GetSerializerType getType) => GetSerializerMethod(typeFullName, getType, writer: true);        /// <summary>        /// Returns a serializer method.        /// </summary>        public SerializerMethodData GetWriteMethod(ITypeSymbol typeSymbol, GetSerializerType getType, bool metadataName, out string nameUsed) => GetSerializerMethod(typeSymbol, getType, metadataName, writer: true, out nameUsed);        /// <summary>        /// Returns a reader.        /// </summary>        public SerializerMethodData GetReadMethod(string typeFullName, GetSerializerType getType) => GetSerializerMethod(typeFullName, getType, writer: false);        /// <summary>        /// Returns a reader.        /// </summary>        public SerializerMethodData GetReadMethod(ITypeSymbol typeSymbol, GetSerializerType getType, bool metadataName, out string nameUsed) => GetSerializerMethod(typeSymbol, getType, metadataName, writer: false, out nameUsed);        /// <summary>        /// Returns a reader.        /// </summary>        private SerializerMethodData GetSerializerMethod(ITypeSymbol typeSymbol, GetSerializerType getType, bool metadataName, bool writer, out string nameUsed)        {            SerializerMethodData sm;                        /* Fullname as named collection (TypeFullName<System.String>).             * This will look for Serializer_TypeFullName<System.String>(). */            nameUsed = typeSymbol.GetTypeSymbolFullNameWithNamedArguments(metadataName);            sm = (writer) ? GetWriteMethod(nameUsed, getType) : GetReadMethod(nameUsed, getType);            if (sm.IsValid())                return sm;            /* Fullname as generic collection (TypeFullName<T0>).             * This will look for Serializer_TypeFullName<T0>(). */            nameUsed = typeSymbol.GetTypeSymbolFullNameWithGenericArguments(metadataName);            sm = (writer) ? GetWriteMethod(nameUsed, getType) : GetReadMethod(nameUsed, getType);            if (sm.IsValid())                return sm;            /* Fullname as generic collection (TypeFullName<T0>).             * This will look for Serializer_TypeFullName<T0>(). */            nameUsed = typeSymbol.GetTypeSymbolNameAsArray(metadataName, GenericArgumentType.ForceGeneric);            sm = (writer) ? GetWriteMethod(nameUsed, getType) : GetReadMethod(nameUsed, getType);            if (sm.IsValid())                return sm;            //If here then nothing was found.            // /* Fullname as-is (TypeFullName).            //  * This will look for Serializer_TypeFullName. */            // nameUsed = GetFullName(typeSymbol, metadataName);            // sm = (writer) ? GetWriteMethod(nameUsed, getType) : GetReadMethod(nameUsed, getType);            // Log($"C NameUsed {nameUsed}. SMValid? {sm.IsValid()}");            // if (sm.IsValid())            //     return sm;            //This is fall through, which indicates failure.            return default;        }        /// <summary>        /// Returns a reader or writer.        /// </summary>        private SerializerMethodData GetSerializerMethod(string typeFullName, GetSerializerType getType, bool writer)        {            SerializerMethodData result = null;            if (getType == GetSerializerType.Full)            {                Dictionary<string, SerializerMethodData> dict = (writer) ? _writeMethods : _readMethods;                dict.TryGetValue(typeFullName, out result);            }            else if (getType == GetSerializerType.Delta)            {                Dictionary<string, SerializerMethodData> dict = (writer) ? _writeDeltaMethods : _readDeltaMethods;                dict.TryGetValue(typeFullName, out result);            }            else if (getType == GetSerializerType.FavorFull || getType == GetSerializerType.FavorDelta)            {                Dictionary<string, SerializerMethodData> dictA;                Dictionary<string, SerializerMethodData> dictB;                if (getType == GetSerializerType.FavorFull)                {                    dictA = (writer) ? _writeMethods : _readMethods;                    dictB = (writer) ? _writeDeltaMethods : _readDeltaMethods;                }                else                {                    dictA = (writer) ? _writeDeltaMethods : _readDeltaMethods;                    dictB = (writer) ? _writeMethods : _readMethods;                }                //Try A first, then B.                if (!dictA.TryGetValue(typeFullName, out result))                    dictB.TryGetValue(typeFullName, out result);            }            else            {                Log($"SerializerType {getType} is unhandled.");            }            if (result == null)                result = new();            return result;        }        /// <summary>        /// Returns the collection containing all delta writers.        /// </summary>        public IReadOnlyDictionary<string, SerializerMethodData> GetWriteMethods() => _writeMethods;        /// <summary>        /// Returns the collection containing all delta writers.        /// </summary>        public IReadOnlyDictionary<string, SerializerMethodData> GetWriteDeltaMethods() => _writeDeltaMethods;        /// <summary>        /// Returns the collection containing all delta readers.        /// </summary>        public IReadOnlyDictionary<string, SerializerMethodData> GetReadMethods() => _readMethods;        /// <summary>        /// Returns the collection containing all delta readers.        /// </summary>        public IReadOnlyDictionary<string, SerializerMethodData> GetReadDeltaMethods() => _readDeltaMethods;        /// <summary>        /// Returns a string to find a serializer of a type as it's full name without any modifications.        /// </summary>        private string GetFullName(ITypeSymbol typeSymbol, bool metadataName) => typeSymbol.GetTypeSymbolFullName(metadataName);        #endregion        /// <summary>        /// Creates a SerializerMethod for Write<T>.        /// </summary>        public SerializerMethodData CreateWriteGenericSerializerMethod(ITypeSymbol typeSymbol, bool metadataName)        {            string typeFullNameWithGenerics = typeSymbol.GetTypeSymbolFullNameWithNamedArguments(metadataName);            return new SerializerMethodData(typeSymbol, $"{FishNetConstants.Writer_Write_Name}<{typeFullNameWithGenerics}>");        }                /// <summary>        /// Creates a SerializerMethod for Read<T>.        /// </summary>        public SerializerMethodData CreateReadGenericSerializerMethod(ITypeSymbol typeSymbol, bool metadataName)        {            string typeFullNameWithGenerics = typeSymbol.GetTypeSymbolFullNameWithNamedArguments(metadataName);            return new SerializerMethodData(typeSymbol, $"{FishNetConstants.Reader_Read_Name}<{typeFullNameWithGenerics}>");        }        /// <summary>        /// Creates a SerializerMethod for WriteDelta<T>.        /// </summary>        public SerializerMethodData CreateWriteDeltaGenericSerializerMethod(ITypeSymbol typeSymbol, bool metadataName)        {            string typeFullNameWithGenerics = typeSymbol.GetTypeSymbolFullNameWithNamedArguments(metadataName);            return new DeltaSerializerMethod(typeSymbol, $"{FishNetConstants.Writer_WriteDelta_Name}<{typeFullNameWithGenerics}>");        }                /// <summary>        /// Creates a SerializerMethod for ReadDelta<T>.        /// </summary>        public SerializerMethodData CreateReadDeltaGenericSerializerMethod(ITypeSymbol typeSymbol, bool metadataName)        {            string typeFullNameWithGenerics = typeSymbol.GetTypeSymbolFullNameWithNamedArguments(metadataName);            return new DeltaSerializerMethod(typeSymbol, $"{FishNetConstants.Reader_ReadDelta_Name}<{typeFullNameWithGenerics}>");        }        /// <summary>        /// Adds default normal writers.        /// </summary>        private void AddDefaultWriteMethods(IAssemblySymbol runtimeAssemblySymbol)        {            Log("");            Log("AddDefaultWriteMethods");            if (!runtimeAssemblySymbol.GetINamedTypeSymbol(FishNetConstants.Writer_FullName, out INamedTypeSymbol? nameTypeSymbol)) return;            if (nameTypeSymbol == null) return;            const bool isMetadataName = false;            //  Log($"<< Symbols count is {nameTypeSymbol.GetMembers().OfType<IMethodSymbol>().Count()}");            foreach (IMethodSymbol methodSymbol in nameTypeSymbol.GetMembers().OfType<IMethodSymbol>())            {                AddSerializerType addType = AddSerializerType.Unset;                //Full write.                if (methodSymbol.HasAttribute(FishNetConstants.DefaultWriterAttribute_FullName, isMetadataName, out _))                    addType = AddSerializerType.Full;                //Delta write.                else if (methodSymbol.HasAttribute(FishNetConstants.DefaultDeltaWriterAttribute_FullName, isMetadataName, out _))                    addType = AddSerializerType.Delta;                bool isDelta = (addType == AddSerializerType.Delta);                int expectedParameters = (isDelta) ? 3 : 1;                //Check for incorrect parameter count.                if (expectedParameters != methodSymbol.Parameters.Length)                    addType = AddSerializerType.Unset;                if (addType == AddSerializerType.Delta)                    AddWriteMethod(new DeltaSerializerMethod(methodSymbol.Parameters[0].Type, methodSymbol.Name), addType);                else if (addType == AddSerializerType.Full)                    AddWriteMethod(new SerializerMethodData(methodSymbol.Parameters[0].Type, methodSymbol.Name), addType);            }        }        /// <summary>        /// Adds default normal writers.        /// </summary>        private void AddDefaultReadMethods(IAssemblySymbol runtimeAssemblySymbol)        {            Log("");            Log("AddDefaultReadMethods");            if (!runtimeAssemblySymbol.GetINamedTypeSymbol(FishNetConstants.Reader_FullName, out INamedTypeSymbol? nameTypeSymbol)) return;            if (nameTypeSymbol == null) return;            const bool isMetadataName = false;            foreach (IMethodSymbol methodSymbol in nameTypeSymbol.GetMembers().OfType<IMethodSymbol>())            {                SerializerMethodData sm = default;                AddSerializerType addType = AddSerializerType.Unset;                //Full.                // Log($"AAAA A {methodSymbol.ReturnType.Kind}");                if (methodSymbol.HasAttribute(FishNetConstants.DefaultReaderAttribute_FullName, isMetadataName, out _))                {                    sm = new SerializerMethodData(methodSymbol.ReturnType, methodSymbol.Name);                    addType = AddSerializerType.Full;                }                //Delta.                else if (methodSymbol.HasAttribute(FishNetConstants.DefaultDeltaReaderAttribute_FullName, isMetadataName, out _))                {                    sm = new DeltaSerializerMethod(methodSymbol.ReturnType, methodSymbol.Name);                    addType = AddSerializerType.Delta;                }                bool isDelta = (addType == AddSerializerType.Delta);                int expectedParameters = (isDelta) ? 1 : 0;                //Check for incorrect parameter count.                if (expectedParameters != methodSymbol.Parameters.Length)                    addType = AddSerializerType.Unset;                if (addType != AddSerializerType.Unset)                    AddReadMethod(sm, addType);            }        }        /// <summary>        /// Returns the parameter name used for values within a generated delta writer.        /// </summary>        public string GetValueParameterName(int parameterIndex) => $"{Generated_ValueParameter_Prefix}{parameterIndex}";        /// <summary>        /// Gets fields which can be serialized over the network.        /// </summary>        public List<IFieldSymbol> GetSerializableFieldSymbols(ITypeSymbol? typeSymbol)        {            List<IFieldSymbol> results = new();            if (typeSymbol == null) return results;            if (typeSymbol is not INamedTypeSymbol namedTypeSymbol) return results;            //Call write for all members.            foreach (ISymbol symbol in namedTypeSymbol.GetMembers())            {                IFieldSymbol? fieldSymbol = symbol as IFieldSymbol;                if (fieldSymbol == null) continue;                if (!CanSerializeFieldSymbol(fieldSymbol)) continue;                results.Add(fieldSymbol);            }            return results;        }        /// <summary>        /// Gets fields which can be serialized over the network.        /// </summary>        /// <param name="namedTypeSymbol"></param>        /// <returns></returns>        public List<IFieldSymbol> GetSerializableFieldSymbols(INamedTypeSymbol? namedTypeSymbol)        {            List<IFieldSymbol> results = new();            if (namedTypeSymbol == null) return results;            //Call write for all members.            foreach (ISymbol symbol in namedTypeSymbol.GetMembers())            {                IFieldSymbol? fieldSymbol = symbol as IFieldSymbol;                if (fieldSymbol == null) continue;                if (!CanSerializeFieldSymbol(fieldSymbol)) continue;                results.Add(fieldSymbol);            }            return results;        }        /// <summary>        /// Returns if a serializer can be generated for a symbol.        /// </summary>        public bool CanSerializeNamedTypeSymbol(INamedTypeSymbol? symbol)        {            if (symbol == null) return false;            if (symbol.IsReadOnly || symbol.IsAbstract || symbol.IsSealed || symbol.IsExtern || symbol.DeclaredAccessibility != Accessibility.Public) return false;            if (symbol.HasAttribute(FishNetConstants.ExcludeSerializationAttribute_FullName, isMetadataName: false)) return false;            return true;        }        /// <summary>        /// Returns true if a symbol can have a serializer generated for it.        /// </summary>        private bool CanSerializeFieldSymbol(IFieldSymbol? symbol)        {            if (symbol == null) return false;            if (symbol.IsReadOnly || symbol.IsAbstract || symbol.IsSealed || symbol.IsConst || symbol.IsExtern || symbol.DeclaredAccessibility != Accessibility.Public) return false;            return true;        }        /// <summary>        /// Returns if a type qualifies for a delta serializer.        /// </summary>        private bool CanCreateSerializer_Internal(INamedTypeSymbol? namedTypeSymbol)        {            if (namedTypeSymbol == null)                return false;            //Not a supported type. Must be a user defined struct or class.            if (!namedTypeSymbol.IsUserDefinedClassOrStruct())                return false;            return true;        }        /// <summary>        /// Returns if a type qualifies for a serializer.        /// </summary>        public bool CanCreateSerializer(INamedTypeSymbol? namedTypeSymbol)        {            return CanCreateSerializer_Internal(namedTypeSymbol);            return true;        }        /// <summary>        /// Returns if a type qualifies for a delta serializer.        /// </summary>        public bool CanCreateDeltaSerializer(INamedTypeSymbol? namedTypeSymbol)        {            if (!CanCreateSerializer_Internal(namedTypeSymbol))                return false;            int memberCount = namedTypeSymbol.MemberNames.Count();            //Too many parameters to process as a delta writer due to not enough flags.            const int maxMemberCount = 62;            if (memberCount >= maxMemberCount)                return false;            return true;        }        private void Log(string txt)        {            if (txt.Length == 0)                Debugg.Log(txt);            else                Debugg.Log($"   [Serializers] {txt}");        }    }}